// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  random,
} from '../remotionShim';


export type HammerSmashProps = Record<string, any>;

const crackPaths = [
  "M 0 0 L -30 -80 L -20 -150 L -90 -250 L -50 -400 L -120 -600 L -80 -900", // Up left
  "M 0 0 L 40 -90 L 20 -180 L 100 -300 L 70 -500 L 180 -700 L 150 -1000", // Up right
  "M 0 0 L 60 70 L 120 120 L 90 250 L 200 400 L 160 650 L 250 900", // Down right
  "M 0 0 L -50 60 L -80 160 L -40 280 L -150 450 L -110 700 L -220 900", // Down left
  "M 0 0 L -100 -20 L -200 10 L -350 -40 L -500 20 L -700 -50 L -900 -20", // Left
  "M 0 0 L 120 30 L 250 -10 L 400 40 L 550 -20 L 750 30 L 900 -10", // Right
  // Small branches
  "M -20 -150 L -60 -180 L -50 -240",
  "M 100 -300 L 160 -320 L 140 -400",
  "M 90 250 L 30 290 L 50 380",
  "M -80 160 L -140 140 L -160 220",
  "M -200 10 L -230 -50 L -300 -40",
  "M 250 -10 L 290 50 L 360 30",
  "M -120 -600 L -180 -620 L -150 -700",
  "M 180 -700 L 250 -680 L 230 -800"
];

const HammerSmash: React.FC<HammerSmashProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 5,
  hammerHeadColor = "#64748b",
  hammerHandleColor = "#92400e",
  crackColor = "#e2e8f0",
  impactTime = 1.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const impactFrame = Math.round(impactTime * fps);
  // Guarantee strictly increasing ranges by enforcing safe offsets
  const safeImpactFrame = Math.max(20, impactFrame);
  const swingStart = safeImpactFrame - 20;
  const strikeStart = safeImpactFrame - 5;
  const recoveryEnd = safeImpactFrame + 15;

  // Hammer Dynamics
  const pitch = interpolate(
    frame,
    [swingStart, strikeStart, safeImpactFrame, recoveryEnd],
    [0, -65, 12, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const roll = interpolate(
    frame,
    [swingStart, strikeStart, safeImpactFrame, recoveryEnd],
    [15, 35, 5, 15],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const hScale = interpolate(
    frame,
    [swingStart, strikeStart, safeImpactFrame],
    [1, 1.4, 0.95],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const hammerSize = Math.min(width, height) * 0.45;

  // Camera Shake (Applied to AbsoluteFill)
  const shakeAmount = interpolate(
    frame,
    [safeImpactFrame, safeImpactFrame + 12],
    [40, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const shakeX = shakeAmount > 0 ? (random(`shake-x-${frame}`) - 0.5) * shakeAmount : 0;
  const shakeY = shakeAmount > 0 ? (random(`shake-y-${frame}`) - 0.5) * shakeAmount : 0;

  // Glass Shards Array
  const shards = Array.from({ length: 18 }).map((_, i) => {
    const angle = i * 20 * (Math.PI / 180);
    const speed = 200 + random(`speed-${i}`) * 600;
    const pFrame = Math.max(0, frame - safeImpactFrame);
    
    const dist = interpolate(
      pFrame,
      [0, 25],
      [0, speed],
      { extrapolateRight: "clamp" }
    );
    
    const opacity = interpolate(
      pFrame,
      [0, 15, 25],
      [1, 1, 0],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
    
    const size = 4 + random(`size-${i}`) * 12;
    const x = width / 2 + Math.cos(angle) * dist;
    const y = height / 2 + Math.sin(angle) * dist;
    const rot = pFrame * (15 + random(`rot-${i}`) * 30);

    if (frame < safeImpactFrame) return null;

    return (
      <div
        key={`shard-${i}`}
        style={{
          position: "absolute",
          left: x,
          top: y,
          width: size,
          height: size,
          backgroundColor: crackColor,
          opacity,
          transform: `translate(-50%, -50%) rotate(${rot}deg)`,
          clipPath: "polygon(50% 0%, 0% 100%, 100% 100%)", // Make them look like glass shards
          transition: "none",
        }}
      />
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        transform: `translate(${shakeX}px, ${shakeY}px)`,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Cracks Layer */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          overflow: "visible",
          transition: "none",
        }}
      >
        <g transform={`translate(${width / 2}, ${height / 2})`}>
          {crackPaths.map((d, i) => {
            const length = 1500;
            const pFrame = Math.max(0, frame - safeImpactFrame);
            const delay = (i % 4) * 1.5;
            
            const progress = interpolate(
              pFrame,
              [delay, delay + 6],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            
            const offset = length - length * progress;

            return (
              <path
                key={`crack-${i}`}
                d={d}
                fill="none"
                stroke={crackColor}
                strokeWidth={i < 6 ? 4 : 2}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={length}
                strokeDashoffset={offset}
                style={{
                  filter: "drop-shadow(0px 0px 3px rgba(255,255,255,0.4))",
                  transition: "none",
                }}
              />
            );
          })}
        </g>
      </svg>

      {/* Shards Layer */}
      {shards}

      {/* Hammer Layer */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          perspective: "1200px",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: width / 2 - hammerSize / 2,
            top: height / 2 - hammerSize / 3.5, // Shift down to align head near screen center
            width: hammerSize,
            height: hammerSize,
            transformOrigin: "bottom center",
            transform: `scale(${hScale}) rotateX(${pitch}deg) rotateZ(${roll}deg)`,
            transformStyle: "preserve-3d",
            transition: "none",
          }}
        >
          <svg viewBox="0 0 100 200" width="100%" height="100%" style={{ transition: "none" }}>
            {/* Hammer Handle */}
            <rect
              x="40"
              y="50"
              width="20"
              height="140"
              rx="8"
              fill={hammerHandleColor}
            />
            {/* Handle Detail/Shadow */}
            <rect
              x="42"
              y="52"
              width="6"
              height="136"
              fill="#ffffff"
              opacity="0.15"
              rx="3"
            />
            <rect
              x="55"
              y="52"
              width="3"
              height="136"
              fill="#000000"
              opacity="0.3"
              rx="1.5"
            />
            
            {/* Hammer Head */}
            <path
              d="M 12 15 h 76 a 6 6 0 0 1 6 6 v 30 a 6 6 0 0 1 -6 6 h -76 a 6 6 0 0 1 -6 -6 v -30 a 6 6 0 0 1 6 -6 z"
              fill={hammerHeadColor}
            />
            {/* Head Detail/Highlight */}
            <path
              d="M 14 18 h 72 a 4 4 0 0 1 4 4 v 6 a 4 4 0 0 1 -4 4 h -72 a 4 4 0 0 1 -4 -4 v -6 a 4 4 0 0 1 4 -4 z"
              fill="#ffffff"
              opacity="0.2"
            />
            {/* Neck Detail */}
            <rect
              x="36"
              y="45"
              width="28"
              height="10"
              rx="3"
              fill={hammerHeadColor}
              opacity="0.8"
            />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HammerSmash;